141|      completeOnboarding: () => set({ isComplete: true }),
142|      reset: () => set(initialState),
143|    }),
144|    {
145|      name: 'ga-onboarding',
146|      partialize: (state) => ({
147|        isComplete: state.isComplete,
148|        selectedProvider: state.selectedProvider,
