45|export function OnboardingWizard() {
46|  const {
47|    step,
48|    selectedProvider,
49|    apiKey,
50|    showApiKey,
51|    connectionStatus,
52|    connectionError,
53|    setStep,
54|    nextStep,
55|    prevStep,
56|    setSelectedProvider,
57|    setApiKey,
58|    toggleShowApiKey,
59|    setConnectionStatus,
60|    setConnectionError,
61|    completeOnboarding,
62|  } = useOnboardingStore();
63|
64|  const { setShowOnboarding, setVoice, voice, setAvatar, avatar, setPersonality, personality, setDesktopPet, desktopPet, backendConfig, setBackendConfig, setApiKey: setApiKeyStore, updateHealth } = useSettingsStore();
65|  const { setCurrentModel, models, setModels, setBackendConnected, setAuthenticated } = useAgentStore();
66|
67|  // Backend connection state
68|  const [backendStatus, setBackendStatus] = useState<'idle' | 'testing' | 'success' | 'error' | 'skipped'>('idle');
69|  const [authPassword, setAuthPassword] = useState('');
70|
71|  const confetti = useMemo(() => {
72|    if (step !== 5) return [];
73|    return Array.from({ length: 30 }, (_, i) => ({
74|      id: i,
75|      x: Math.random() * 100,
76|      color: ['#7c3aed', '#a78bfa', '#22c55e', '#f59e0b', '#ef4444', '#3b82f6'][Math.floor(Math.random() * 6)],
77|      delay: Math.random() * 2,
78|    }));
79|  }, [step]);
80|
81|  const canProceed = () => {
82|    switch (step) {
83|      case 0: return true;
84|      case 1: return backendStatus === 'success' || backendStatus === 'skipped';
85|      case 2: return !!selectedProvider;
86|      case 3: return selectedProvider === 'ollama' || apiKey.length >= 10;
87|      case 4: return true;
88|      case 5: return true;
89|      default: return false;
90|    }
91|  };
92|
93|  // Test backend connection (with 10s timeout)
94|  const handleTestBackend = async () => {
95|    setBackendStatus('testing');
96|
97|    const timeoutPromise = new Promise<false>((resolve) =>
98|      setTimeout(() => resolve(false), 10000)
99|    );
100|
101|    const healthPromise = checkBackendHealth().then((result) => result || false);
102|
103|    const isHealthy = await Promise.race([healthPromise, timeoutPromise]);
104|
105|    if (isHealthy) {
106|      setBackendStatus('success');
107|      setBackendConnected('connected');
108|
109|      try {
110|        // Try to authenticate
111|        const authResult = await loginToBackend(authPassword || undefined);
112|        if (authResult.success) {
113|          setAuthenticated(true);
114|        }
115|
116|        // Load models
117|        const modelsData = await getModels();
118|        setModels(modelsData);
119|
120|        // Update health
121|        updateHealth({ lastCheck: Date.now() });
122|      } catch (err) {
123|        setBackendStatus('error');
124|      }
125|    } else {
126|      setBackendStatus('error');
127|      setBackendConnected('disconnected');
128|    }
129|  };
130|
131|  const handleTestConnection = useCallback(async () => {
132|    if (!selectedProvider) return;
133|    setConnectionStatus('testing');
134|    setConnectionError(null);
135|
136|    try {
137|      const result = await testConnection(selectedProvider, apiKey);
138|      if (result.success) {
139|        setConnectionStatus('success');
140|        if (apiKey) {
141|          setApiKeyStore(selectedProvider, apiKey);
142|        }
143|      } else {
144|        setConnectionStatus('error');
145|        setConnectionError(result.error || 'Connection failed');
146|      }
147|    } catch {
148|      setConnectionStatus('error');
149|      setConnectionError('Network error. Please check your connection.');
150|    }
151|  }, [selectedProvider, apiKey, setConnectionStatus, setConnectionError, setApiKeyStore]);
152|
153|  const handleFinish = () => {
154|    completeOnboarding();
155|    setShowOnboarding(false);
156|
