1|//! Shadow Agent Desktop App — Tauri v2 Main Entry Point
2|//!
3|//! This file sets up the Tauri application with:
4|//! - Python FastAPI backend sidecar management (auto-start on launch)
5|//! - Custom Tauri commands for frontend integration
6|//! - Native file dialog support
7|//! - Proper exit handling
8|//! - File logging for diagnostics (even in release mode)
9|
10|#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
11|
12|use serde::{Deserialize, Serialize};
13|use std::fs::{self, File, OpenOptions};
14|use std::io::Write;
15|use std::process::Command;
16|use std::sync::{Arc, Mutex};
17|use tauri::Emitter;
18|use tauri::Manager;
19|use tauri_plugin_dialog::DialogExt;
20|use tauri_plugin_shell::ShellExt;
21|
22|const BACKEND_PORT: u16 = 8765;
23|
24|// ═══════════════════════════════════════════════════════════════
25|//  File Logger — writes to %APPDATA%/com.shadowagent.desktop/
26|// ═══════════════════════════════════════════════════════════════
27|
28|struct FileLogger {
29|    file: Mutex<Option<File>>,
30|}
31|
32|impl FileLogger {
33|    fn new() -> Self {
34|        let file = Self::get_log_file();
35|        Self {
36|            file: Mutex::new(file.ok()),
37|        }
38|    }
39|
40|    fn get_log_file() -> Result<File, std::io::Error> {
41|        let log_dir = Self::get_log_dir()?;
42|        fs::create_dir_all(&log_dir)?;
43|
44|        // Create a timestamped log file
45|        let now = std::time::SystemTime::now()
46|            .duration_since(std::time::UNIX_EPOCH)
47|            .unwrap_or_default()
48|            .as_secs();
49|        let log_path = log_dir.join(format!("shadowagent_{}.log", now));
50|
51|        let file = OpenOptions::new()
52|            .create(true)
53|            .append(true)
54|            .open(&log_path)?;
55|
56|        // latest.log is now updated on each log write (see log() method)
57|        Ok(file)
58|    }
59|
60|    fn get_log_dir() -> Result<std::path::PathBuf, std::io::Error> {
61|        #[cfg(target_os = "windows")]
62|        {
63|            let appdata = std::env::var("APPDATA").unwrap_or_else(|_| ".".to_string());
64|            Ok(std::path::PathBuf::from(appdata)
65|                .join("com.shadowagent.desktop")
66|                .join("logs"))
67|        }
68|        #[cfg(not(target_os = "windows"))]
69|        {
70|            let home = std::env::var("HOME").unwrap_or_else(|_| ".".to_string());
71|            Ok(std::path::PathBuf::from(home)
72|                .join(".shadowagent")
73|                .join("logs"))
74|        }
75|    }
76|
77|    fn log(&self, level: &str, msg: &str) {
78|        let timestamp = std::time::SystemTime::now()
79|            .duration_since(std::time::UNIX_EPOCH)
80|            .unwrap_or_default()
81|            .as_secs();
82|
83|        let line = format!("[{}] {:10} {}\n", timestamp, level, msg);
84|
85|        // Write to file
86|        if let Ok(mut guard) = self.file.lock() {
87|            if let Some(ref mut f) = *guard {
88|                let _ = f.write_all(line.as_bytes());
89|                let _ = f.flush();
90|            }
91|        }
92|
93|        // Also append to latest.log for easy access
94|        if let Ok(log_dir) = Self::get_log_dir() {
95|            let latest_path = log_dir.join("latest.log");
96|            if let Ok(mut latest) = OpenOptions::new()
97|                .create(true)
98|                .append(true)
99|                .open(&latest_path)
100|            {
101|                let _ = latest.write_all(line.as_bytes());
102|            }
103|        }
104|
105|        // Also print to stderr (console)
106|        eprint!("{}", line);
107|    }
