209|// ═══════════════════════════════════════════════════════════════
210|//  Helper: Kill a process by PID (cross-platform)
211|// ═══════════════════════════════════════════════════════════════
212|
213|fn kill_process(pid: u32) {
214|    #[cfg(target_os = "windows")]
215|    {
216|        let _ = Command::new("taskkill")
217|            .args(["/F", "/PID", &pid.to_string()])
218|            .output();
219|    }
220|    #[cfg(unix)]
221|    {
222|        // Try SIGTERM first for graceful shutdown
223|        let _ = Command::new("kill")
224|            .args(["-15", &pid.to_string()])
225|            .output();
226|        // Wait up to 3 seconds for graceful shutdown
227|        let mut exited = false;
228|        for _ in 0..15 {
229|            std::thread::sleep(std::time::Duration::from_millis(200));
230|            let check = Command::new("kill")
231|                .args(["-0", &pid.to_string()])
232|                .output();
233|            if check.is_err() || !check.unwrap().status.success() {
234|                exited = true;
235|                break;
236|            }
237|        }
238|        if !exited {
239|            // Force kill as last resort
240|            let _ = Command::new("kill")
241|                .args(["-9", &pid.to_string()])
242|                .output();
243|        }
244|    }
