251|/// Start the Python backend sidecar process
252|#[tauri::command]
253|async fn start_backend(app: tauri::AppHandle, state: tauri::State<'_, AppState>) -> Result<bool, String> {
254|    let mut backend = state.backend.lock().map_err(|e| e.to_string())?;
255|
256|    if backend.running {
257|        log_info(&format!("Backend already running (pid: {:?})", backend.pid));
258|        return Ok(true);
259|    }
260|
261|    let sidecar_command = app
262|        .shell()
263|        .sidecar("backend")
264|        .map_err(|e| format!("Failed to create sidecar command: {}", e))?;
265|
266|    match sidecar_command.spawn() {
267|        Ok((mut rx, child)) => {
268|            let pid = child.pid();
269|            backend.running = true;
270|            backend.pid = Some(pid as u32);
271|            backend.child_pid = Some(pid as u32);
272|            log_info(&format!("Backend sidecar started with PID: {}", pid));
273|
274|            let app_handle = app.clone();
275|            let backend_arc = state.backend.clone();
276|            tauri::async_runtime::spawn(async move {
277|                use tauri_plugin_shell::process::CommandEvent;
278|                while let Some(event) = rx.recv().await {
279|                    match event {
280|                        CommandEvent::Stdout(line) => {
281|                            log_info(&format!("[backend stdout] {}", String::from_utf8_lossy(&line)));
282|                        }
283|                        CommandEvent::Stderr(line) => {
284|                            log_warn(&format!("[backend stderr] {}", String::from_utf8_lossy(&line)));
285|                        }
286|                        CommandEvent::Terminated(status) => {
287|                            log_warn(&format!("Backend sidecar terminated: {:?}", status));
288|                            if let Ok(mut b) = backend_arc.lock() {
289|                                b.running = false;
290|                                b.pid = None;
291|                                b.child_pid = None;
292|                            }
293|                            let _ = app_handle.emit("backend-crashed", ());
294|                            break;
295|                        }
296|                        CommandEvent::Error(err) => {
297|                            log_error(&format!("[backend error] {}", err));
298|                        }
299|                        _ => {}
300|                    }
301|                }
302|            });
303|
304|            Ok(true)
305|        }
306|        Err(e) => {
307|            log_error(&format!("Failed to start backend sidecar: {}", e));
308|            Err(format!("Failed to start backend: {}", e))
309|        }
310|    }
311|}
