313|/// Stop the Python backend sidecar process
314|#[tauri::command]
315|async fn stop_backend(state: tauri::State<'_, AppState>) -> Result<bool, String> {
316|    let mut backend = state.backend.lock().map_err(|e| e.to_string())?;
317|
318|    if !backend.running {
319|        return Ok(true);
320|    }
321|
322|    if let Some(pid) = backend.child_pid {
323|        kill_process(pid);
324|    }
325|
326|    // Brief sleep to allow the process to actually exit
327|    // before we report it as not running
328|    std::thread::sleep(std::time::Duration::from_millis(500));
329|
330|    backend.running = false;
331|    backend.pid = None;
332|    backend.child_pid = None;
333|    log_info("Backend sidecar stopped");
334|    Ok(true)
335|}
