348|/// Open a native file picker dialog
349|#[tauri::command]
350|async fn open_file_dialog(
351|    app: tauri::AppHandle,
352|    title: Option<String>,
353|    filters: Option<Vec<FileFilter>>,
354|    multiple: Option<bool>,
355|) -> Result<FileDialogResult, String> {
356|    use tokio::sync::oneshot;
357|    
358|    let (tx, rx) = oneshot::channel();
359|    let dialog = app.dialog();
360|    let title_str = title.unwrap_or_else(|| "Select File".to_string());
361|
362|    let mut file_dialog = dialog.file();
363|    file_dialog = file_dialog.set_title(&title_str);
364|
365|    if let Some(filter_list) = filters {
366|        for f in filter_list {
367|            let ext_strs: Vec<&str> = f.extensions.iter().map(|s| s.as_str()).collect();
368|            file_dialog = file_dialog.add_filter(&f.name, &ext_strs);
369|        }
370|    }
371|
372|    if multiple.unwrap_or(false) {
373|        file_dialog.pick_files(move |result| {
374|            let _ = tx.send(result);
375|        });
376|    } else {
377|        file_dialog.pick_file(move |result| {
378|            let _ = tx.send(result.map(|p| vec![p]));
379|        });
380|    }
381|    
382|    let result = rx.await.map_err(|e| e.to_string())?;
383|    Ok(FileDialogResult {
384|        paths: result.map(|paths| paths.into_iter().map(|p| p.to_string()).collect()),
385|    })
386|}
